def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return clamp_step(b - a)

    def pos(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def closest(targets, s):
        best = None
        best_d = None
        for t in targets or []:
            p = pos(t, None)
            if p is None:
                continue
            d = manhattan(p, s)
            if best is None or d < best_d:
                best, best_d = p, d
        return best

    def farthest(targets, s):
        best = None
        best_d = None
        for t in targets or []:
            p = pos(t, None)
            if p is None:
                continue
            d = manhattan(p, s)
            if best is None or d > best_d:
                best, best_d = p, d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            tx, ty = ox, oy
            return [step_toward(sx, tx), step_toward(sy, ty)]
        corners = []
        if grid_w and grid_h:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = farthest(corners, (ox, oy)) or farthest(corners, (sx, sy)) or (sx, sy)
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = closest(targets, (sx, sy))
        if best is None:
            # drift toward opponent when nothing explicit is provided
            return [step_toward(sx, ox), step_toward(sy, oy)]
        # mild tie-break: prefer horizontal progress first if equal
        dx = step_toward(sx, best[0])
        dy = step_toward(sy, best[1])
        if dx == 0 and dy == 0:
            return [0, 0]
        return [dx, dy]

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("items") or []
    if resources:
        best = closest(resources, (sx, sy))
        if best is not None:
            dx = step_toward(sx, best[0])
            dy = step_toward(sy, best[1])
            # simple denial/avoidance: if opponent is closer to the same resource, sidestep slightly
            if manhattan((ox, oy), best) <= manhattan((sx, sy), best):
                if abs(best[0] - sx) >= abs(best[1] - sy):
                    dy = 0 if sy == oy else step_toward(sy, sy + (1 if sy >= oy else -1))
                else:
                    dx = 0 if sx == ox else step_toward(sx, sx + (1 if sx >= ox else -1))
            return [dx, dy]

    # fallback: either chase opponent weakly or stay put if no info
    if ox == sx and oy == sy:
        return [0, 0]
    return [step_toward(sx, ox), step_toward(sy, oy)]

